import {commercialRoute} from './commercial.js?v=public1';
import {seedData,INSURERS,PRODUCTS,STAGES,REFERENCE_DATE} from './data.js';
import {daysUntil,requestDocuments,demoTimestamp,uid,event,validateIntake,prepareRequests,simulateResponses,resolveRequest,chooseQuote,customerDraft,sendDraft,addLead,convertLead,noteCase} from './domain.js';

const KEY='arias.mesa.v1';
let state,storageOK=true;
try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):seedData();if(state.version!==1||!Array.isArray(state.clients))throw Error('Versión incompatible');}catch{state=seedData();storageOK=false;}
const money=n=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(n);
const date=(d,opts={day:'numeric',month:'short'})=>d?new Intl.DateTimeFormat('es-CO',{...opts,timeZone:'America/Bogota'}).format(new Date(d.length===10?d+'T12:00:00-05:00':d)):'Por confirmar';
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const client=id=>state.clients.find(c=>c.id===id);
const policy=id=>state.policies.find(p=>p.id===id);
const caseBy=id=>state.cases.find(c=>c.id===id);
const insurer=id=>INSURERS.find(i=>i.id===id);
const shapes={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3a4 4 0 0 1 0 8"/>',shield:'<path d="M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7Z"/><path d="m8 12 3 3 5-6"/>',folder:'<path d="M3 7V4h6l3 3h9v13H3Z"/>',quote:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M8 9h8M8 13h5M8 17h8"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',connect:'<path d="M8 3v4M16 3v4M5 7h14v4a7 7 0 0 1-14 0ZM12 18v4"/>',growth:'<path d="M3 18 9 12l4 3 8-11M15 4h6v6"/>',note:'<path d="M4 3h16v18H4ZM8 8h8M8 12h8M8 16h4"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',left:'<path d="M20 12H4m6-6-6 6 6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',alert:'<path d="m12 3 10 18H2Z"/><path d="M12 9v5m0 3v.1"/>',file:'<path d="M14 2H5v20h14V7Z"/><path d="M14 2v6h5M8 13h8M8 17h6"/>',plus:'<path d="M12 4v16M4 12h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 8M20 2v6h-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',play:'<path d="m8 4 12 8-12 8Z"/>',car:'<path d="m5 6 2-3h10l2 3 2 5v8h-3v-3H6v3H3v-8Z"/><path d="M4 9h16M6 13h2m8 0h2"/>',building:'<path d="M4 22V5h10v17M14 11h6v11M2 22h20M8 9h2m-2 4h2m-2 4h2m6-2h2m-2 4h2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',plane:'<path d="m22 2-8 20-3-9-9-3Z"/><path d="m22 2-11 11"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',edit:'<path d="m15 4 5 5M3 21l5-1L21 7l-5-5L3 15Z"/>',save:'<path d="M4 3h13l4 4v14H3V3ZM7 3v7h10V3M7 21v-7h10v7"/>',external:'<path d="M14 3h7v7M21 3l-9 9M10 3H3v18h18v-7"/>',send:'<path d="m22 2-7 20-4-9-9-4Z"/><path d="m22 2-11 11"/>',layers:'<path d="m12 3 10 5-10 5L2 8ZM2 13l10 5 10-5M2 18l10 5 10-5"/>',book:'<path d="M12 5C9 2 4 3 2 4v16c3-2 7-2 10 0 3-2 7-2 10 0V4c-3-1-7-2-10 1ZM12 5v15"/>'};
function icon(name,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.file}</svg>`;}
const badge=(text,color='')=>`<span class="badge ${color}">${e(text)}</span>`;
const button=(text,action,id='',cls='',ic='')=>`<button type="button" class="btn ${cls}" data-action="${action}" data-id="${e(id)}">${ic?icon(ic):''}${e(text)}</button>`;
const link=(text,href,cls='',ic='')=>`<a class="btn ${cls}" href="#${href}">${ic?icon(ic):''}${e(text)}</a>`;
const avatar=(c,large=false)=>`<span class="avatar ${c.type==='Empresa'?'blue':''} ${large?'large':''}" aria-hidden="true">${e(c.initials)}</span>`;
const note=text=>`<p class="page-note">${icon('info')}${text}</p>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('El navegador no pudo guardar los cambios. Exporta una copia antes de cerrar.',true);}}
function toast(msg,error=false){const el=document.getElementById('toast');el.textContent=msg;el.className=`show ${error?'error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',5000);}
function route(){const [path,q='']=(location.hash.slice(1)||'sitio').split('?');return {path,parts:path.split('/'),params:new URLSearchParams(q)};}
const pageTitle=(title,sub,actions='')=>`<div class="page-heading"><div><h1>${e(title)}</h1><p>${e(sub)}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
const empty=(title,body,action='')=>`<div class="empty">${icon('folder')}<h3>${e(title)}</h3><p>${e(body)}</p>${action}</div>`;
function shell(page,key){const pending=state.intake.filter(x=>x.status==='pending').length;const nav=[['inicio','home','Mi día'],['clientes','users','Clientes'],['polizas','shield','Pólizas'],['cotizaciones','quote','Cotizaciones'],['mensajes','mail','Comunicaciones'],['documentos','folder','Documentos']];const explore=[['sitio','external','Vista comercial'],['incorporar','layers','Incorporar información',pending],['oportunidades','growth','Nuevos negocios'],['conexiones','connect','Conexiones futuras'],['reunion','note','Reunión familiar']];const current=[...nav,...explore].find(n=>n[0]===key)?.[2]||'Expediente';return `<div class="shell"><aside class="sidebar"><a href="#inicio" class="brand" aria-label="Arias, inicio"><img class="app-monogram" src="images/arias-monogram.svg" alt="" width="42" height="42"><span class="app-wordmark">Asesores de Seguros<small>Arias &amp; Cía. Ltda.</small></span></a><nav aria-label="Navegación principal"><div class="nav-group"><span class="nav-label">Mesa de trabajo</span>${nav.map(([id,ic,label])=>`<a class="nav-link ${key===id?'active':''}" ${key===id?'aria-current="page"':''} href="#${id}">${icon(ic)}${label}</a>`).join('')}</div><div class="nav-group"><span class="nav-label">Diseñar el siguiente paso</span>${explore.map(([id,ic,label,n])=>`<a class="nav-link ${key===id?'active':''}" ${key===id?'aria-current="page"':''} href="#${id}">${icon(ic)}${label}${n?`<span class="nav-count">${n}</span>`:''}</a>`).join('')}</div></nav><div class="sidebar-bottom"><div class="demo-label">${icon('book')}Edición de trabajo</div><p>Un recorrido del negocio con información completamente ficticia.</p><button data-action="guide">${icon('play')}Recorrer la presentación</button><button data-action="export">${icon('download')}Exportar el ejercicio</button><button data-action="reset">${icon('refresh')}Restablecer datos</button><div class="sidebar-footer"><span>Arias & Cía.</span><span>Octubre 2026</span></div></div></aside><div class="workspace">${!storageOK?'<div class="storage-warning">No se pudo leer o guardar el almacenamiento local. Exporta tus cambios antes de cerrar.</div>':''}<header class="topbar"><div class="breadcrumb">Mesa de seguros ${icon('chevron')}<strong>${e(current)}</strong></div><div class="top-actions"><form id="global-search" class="search-form" role="search">${icon('search')}<input name="query" aria-label="Buscar cliente o póliza" placeholder="Buscar cliente o póliza…" autocomplete="off"><button class="sr-only" type="submit">Buscar</button></form><span class="top-divider"></span><button class="btn small" data-action="guide">${icon('play')}Guía del demo</button><span class="top-avatar" title="Sesión de demostración">DE</span></div></header><main class="content" id="main" tabindex="-1">${page}<footer class="foot-line"><span>Datos ficticios · Sin conexiones ni envíos externos</span><span>Fecha del escenario: 21 oct. 2026 · Guardado en este navegador</span></footer></main></div></div>`;}
function dayLabel(p){const d=daysUntil(p.end);if(state.policies.some(n=>n.previousId===p.id))return '<span class="days">Vigencia anterior</span>';return `<span class="days ${d<=7?'urgent':''}">${d<0?`Venció hace ${Math.abs(d)} días`:d===0?'Vence hoy':`En ${d} días`}</span>`;}
function renewalTable(policies,compact=false){return `<div class="table-wrap"><table><thead><tr><th>Cliente / póliza</th><th>Producto</th><th>Vencimiento</th>${compact?'':'<th>Prima anual · COP</th><th>Información</th>'}<th><span class="sr-only">Abrir</span></th></tr></thead><tbody>${policies.map(p=>{const c=client(p.clientId);const cs=state.cases.find(x=>x.policyId===p.id);return `<tr><td><div class="client-cell">${avatar(c)}<div><a class="client-name" href="#cliente/${c.id}">${e(c.name)}</a><small>${e(p.number)}</small></div></div></td><td>${e(p.product)}<small>${e(p.insurer)} · simulada</small></td><td>${date(p.end)}<small>${dayLabel(p)}</small></td>${compact?'':`<td>${money(p.premium)}</td><td>${badge(p.validated?'Revisada':'Por validar',p.validated?'green':'gold')}</td>`}<td><a class="icon-button" href="#${cs?'caso/'+cs.id:'cliente/'+c.id}" aria-label="Abrir ${e(cs?.title||c.name)}">${icon('arrow')}</a></td></tr>`;}).join('')}</tbody></table></div>`;}
function dashboard(){const upcoming=state.policies.filter(p=>!state.policies.some(n=>n.previousId===p.id)&&daysUntil(p.end)>=0&&daysUntil(p.end)<=30).sort((a,b)=>a.end.localeCompare(b.end));const pending=state.intake.filter(i=>i.status==='pending').length;const c=caseBy('r01');const validated=policy('p01').validated;const requests=state.requests.filter(r=>r.caseId==='r01');const hasQuotes=requests.some(r=>r.quote);const featureNext=c.stage==='cerrada'?'Ver renovación completada':!validated?'Confirmar vigencia':!requests.length?'Preparar cotizaciones':c.stage==='presentada'?'Ver seguimiento':hasQuotes?'Comparar propuestas':'Revisar solicitudes';const featureHref=!validated?'incorporar':hasQuotes&&c.stage!=='cerrada'?'caso/r01?tab=comparar':'caso/r01';return `${pageTitle('El negocio, al día.','Miércoles 21 de octubre · Una vista clara de lo que sigue.',button('Nuevo negocio','new-case','','','plus'))}<div class="overview"><section class="focus-area"><div><div class="focus-top">${badge('Renovación próxima','gold')}<span>Elena Montes · Automóvil</span></div><h2>Una póliza. Todo su recorrido.</h2><p>${c.stage==='cerrada'?'La nueva vigencia quedó vinculada a la anterior. El historial conserva documentos, propuestas y la entrega simulada.':!validated?'La carátula y la fecha capturada no coinciden. Confirma la vigencia para preparar la renovación.':hasQuotes?'Las respuestas ya están en el expediente. Revisa las diferencias antes de preparar el mensaje a Elena.':'Información revisada. Prepara solicitudes a varias aseguradoras desde el mismo expediente.'}</p></div><div class="actions">${link(featureNext,featureHref,'gold','arrow')}${link('Abrir expediente','cliente/c01','ghost on-dark')}</div><div class="focus-orbit" aria-hidden="true"></div></section><section class="portfolio-summary"><h2>La cartera del ejercicio</h2><div class="stat-row"><span>Pólizas registradas</span><strong>${state.policies.length}</strong></div><div class="stat-row"><span>Vencen en los próximos 30 días</span><strong>${upcoming.length}</strong></div><div class="stat-row"><span>Expedientes por revisar</span><strong>${pending}</strong></div><div class="summary-foot"><span>${state.clients.length} clientes ficticios</span><a class="text-link" href="#polizas">Ver cartera ${icon('arrow')}</a></div></section></div><div class="main-grid"><section><div class="section-header"><h2>Renovaciones en el horizonte</h2><a class="text-link" href="#polizas?range=30">Ver todas ${icon('arrow')}</a></div><div class="panel">${renewalTable(upcoming.slice(0,4),true)}</div>${note('La agenda se calcula desde las vigencias registradas. Los datos pendientes de revisión están señalados.')}</section><section><div class="section-header"><h2>Lo que necesita atención</h2></div><div class="queue"><div class="queue-item">${icon(validated?'check':'alert')}<div><h3>${validated?'Vigencia de Elena confirmada':'Una fecha por confirmar'}</h3><p>${validated?'Ya puedes reutilizar la información para cotizar.':'Documento fuente: 5 nov. · extracción: 15 nov.'}</p></div>${link(validated?'Cotizar':'Revisar',validated?'caso/r01':'incorporar','','')}</div><div class="queue-item">${icon('file')}<div><h3>${state.intake[1].status==='done'?'Soporte incorporado':'Un soporte pendiente'}</h3><p>Estudio Roble Demo · programa empresarial.</p></div>${link('Ver','incorporar','','')}</div><div class="queue-item">${icon('mail')}<div><h3>${state.messages.length} ${state.messages.length===1?'comunicación':'comunicaciones'} en el ejercicio</h3><p>Mensajes y solicitudes vinculados al negocio.</p></div>${link('Abrir','mensajes','','')}</div><div class="queue-foot"><a class="text-link" href="#reunion">Preparar la conversación familiar ${icon('arrow')}</a></div></div></section></div><div class="journey-strip"><span>El mismo caso, de principio a fin</span><span>Expediente ${icon('chevron')}</span><span>Cotización ${icon('chevron')}</span><span>Comparación ${icon('chevron')}</span><span>Cliente ${icon('chevron')}</span><span>Historial</span></div>`;}
function clientsPage(params){const q=params.get('q')||'';const results=state.clients.filter(c=>`${c.name} ${c.identity} ${c.email} ${state.policies.filter(p=>p.clientId===c.id).map(p=>p.number).join(' ')}`.toLowerCase().includes(q.toLowerCase()));return `${pageTitle('Clientes','Un expediente reúne personas, pólizas y conversaciones.',button('Crear cliente ficticio','new-client','','primary','plus'))}<form class="toolbar" id="filter-clients"><input name="q" value="${e(q)}" aria-label="Buscar en clientes" placeholder="Nombre, identificación o número de póliza"><button class="btn" type="submit">${icon('search')}Buscar</button>${q?link('Limpiar','clientes','ghost'):''}</form><div class="section-header"><p>${results.length} de ${state.clients.length} expedientes</p></div><div class="panel">${results.length?`<div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Contacto de muestra</th><th>Pólizas</th><th>Próximo vencimiento</th><th></th></tr></thead><tbody>${results.map(c=>{const ps=state.policies.filter(p=>p.clientId===c.id&&!state.policies.some(n=>n.previousId===p.id)).sort((a,b)=>a.end.localeCompare(b.end));return `<tr><td><div class="client-cell">${avatar(c)}<div><a class="client-name" href="#cliente/${c.id}">${e(c.name)}</a><small>${e(c.identity)} · ${e(c.type)}</small></div></div></td><td>${e(c.email)}<small>${e(c.city)} · ${e(c.channel)}</small></td><td>${ps.length}</td><td>${ps[0]?`${date(ps[0].end)}<small>${e(ps[0].product)}</small>`:'Sin pólizas'}</td><td><a class="icon-button" href="#cliente/${c.id}" aria-label="Abrir expediente de ${e(c.name)}">${icon('arrow')}</a></td></tr>`;}).join('')}</tbody></table></div>`:empty('No encontramos ese expediente','Prueba con otro nombre o limpia la búsqueda.',link('Mostrar clientes','clientes'))}</div>`;}
function timeline(clientId,caseId,limit=20){const list=state.events.filter(ev=>caseId?ev.caseId===caseId:ev.clientId===clientId).slice(0,limit);return list.length?`<div class="timeline">${list.map(ev=>`<article class="timeline-item"><h3>${e(ev.title)}</h3><p>${e(ev.detail)}</p><small>${date(ev.at,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})} · ${e(ev.actor)}</small></article>`).join('')}</div>`:empty('El historial empieza aquí','Las gestiones que registres quedarán vinculadas al expediente.');}
function docRows(docs){return docs.map(d=>`<div class="document-row">${icon('file')}<div><h3>${e(d.title)}</h3><p>${e(d.type)} · ${date(d.date)} · ${e(d.status)}</p></div>${button('Abrir','document',d.id,'small','external')}</div>`).join('');}
function clientPage(id){const c=client(id);if(!c)return notFound();const ps=state.policies.filter(p=>p.clientId===id),cs=state.cases.filter(x=>x.clientId===id),docs=state.documents.filter(d=>d.clientId===id);return `<a href="#clientes" class="back">${icon('left')}Todos los clientes</a><div class="record-header">${avatar(c,true)}<div><h1>${e(c.name)}</h1><p>${e(c.identity)} · ${e(c.type)} · Expediente ficticio</p></div><div class="actions">${button('Editar ficha','edit-client',id,'','edit')}${button('Nuevo negocio','new-case',id,'primary','plus')}</div></div><dl class="record-facts"><div><dt>Correo de muestra</dt><dd>${e(c.email)}</dd></div><div><dt>Ciudad</dt><dd>${e(c.city)}</dd></div><div><dt>Canal preferido</dt><dd>${e(c.channel)}</dd></div><div><dt>Pólizas registradas</dt><dd>${ps.length}</dd></div><div><dt>Casos abiertos</dt><dd>${cs.filter(x=>x.stage!=='cerrada').length}</dd></div><div><dt>Información</dt><dd>${badge(ps.every(p=>p.validated)?'Revisada':'Hay datos por validar',ps.every(p=>p.validated)?'green':'gold')}</dd></div></dl><div class="split"><div><section><div class="section-header"><h2>Pólizas y riesgos</h2></div>${ps.length?ps.map(p=>`<article class="policy-row">${icon(p.product==='Automóvil'?'car':p.product==='Hogar'?'home':p.product==='Vida'?'heart':'shield')}<div><h3>${e(p.product)} ${!p.validated?badge('Por validar','gold'):''}</h3><p>${e(p.number)} · ${e(p.insurer)} · simulada</p><p>${e(p.risk)}</p></div><div class="policy-action"><small>${dayLabel(p)} · ${date(p.end)}</small>${button('Ver carátula','document',p.docId,'small')}</div></article>`).join(''):empty('Sin pólizas registradas','La oportunidad puede existir antes de que se emita una póliza.')}</section><section class="section-space"><div class="section-header"><h2>Negocios en seguimiento</h2></div>${cs.map(ca=>`<article class="queue-item">${icon('quote')}<div><h3>${e(ca.title)}</h3><p>${e(ca.next)} · ${STAGES[ca.stage]}</p></div>${link('Abrir caso','caso/'+ca.id,'small','arrow')}</article>`).join('')||empty('Sin casos abiertos','Crea un negocio para registrar la siguiente gestión.',button('Nuevo negocio','new-case',id))}</section><section class="section-space"><div class="section-header"><h2>Documentos del expediente</h2></div>${docRows(docs)||empty('Sin documentos de muestra','Los documentos se vinculan a cliente, póliza o caso.')}</section></div><aside><div class="panel panel-pad"><h2>Contexto del cliente</h2><p class="intro-prose" style="margin:12px 0 0">${e(c.note)}</p></div><section class="section-space"><div class="section-header"><h2>Historia del expediente</h2></div>${timeline(id,null,10)}</section></aside></div>`;}
function policiesPage(params){const range=params.get('range')||'all',product=params.get('product')||'all';const list=state.policies.filter(p=>(range==='all'||!state.policies.some(n=>n.previousId===p.id)&&daysUntil(p.end)>=0&&daysUntil(p.end)<=Number(range))&&(product==='all'||p.product===product)).sort((a,b)=>a.end.localeCompare(b.end));return `${pageTitle('Pólizas y vencimientos','El calendario del negocio, con documentos que respaldan cada fecha.',button('Exportar ejercicio','export','','','download'))}<form class="toolbar" id="filter-policies"><select name="range" aria-label="Horizonte de vencimientos">${[['all','Todas las vigencias'],['7','Próximos 7 días'],['30','Próximos 30 días'],['60','Próximos 60 días']].map(([v,t])=>`<option value="${v}" ${range===v?'selected':''}>${t}</option>`).join('')}</select><select name="product" aria-label="Filtrar por producto"><option value="all">Todos los productos</option>${PRODUCTS.map(v=>`<option ${v===product?'selected':''}>${e(v)}</option>`).join('')}</select><button class="btn" type="submit">Aplicar filtros</button><span class="muted">${list.length} pólizas</span></form><div class="panel">${list.length?renewalTable(list):empty('No hay pólizas en este filtro','Amplía el horizonte o consulta otro producto.',link('Mostrar todas','polizas'))}</div>${note('Las primas están expresadas por año en COP y son ilustrativas. Registrar una fecha no confirma cobertura ni estado de pago.')}`;}
function casesPage(){return `${pageTitle('Mesa de cotización','Una captura de información. Varias solicitudes y todo el seguimiento.',button('Nuevo negocio','new-case','','primary','plus'))}<div class="callout info">${icon('info')}<div><strong>Conectores de demostración</strong><p>Automóvil tiene un recorrido completo con tres entidades ficticias. Los demás productos permiten explorar el expediente y sus siguientes pasos.</p></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Caso / cliente</th><th>Etapa</th><th>Próxima acción</th><th>Fecha de gestión</th><th></th></tr></thead><tbody>${state.cases.map(c=>`<tr><td><a class="client-name" href="#caso/${c.id}">${e(c.title)}</a><small>${e(client(c.clientId)?.name)}</small></td><td>${badge(STAGES[c.stage],c.stage==='preparacion'?'gold':c.stage==='cerrada'?'green':'blue')}</td><td>${e(c.next)}</td><td>${date(c.due)}${daysUntil(c.due)<0?`<small>${badge('Atrasada','red')}</small>`:''}</td><td><a class="icon-button" href="#caso/${c.id}" aria-label="Abrir ${e(c.title)}">${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div></div>`;}
const requestLabels={prepared:['Preparada','blue'],quoted:['Propuesta recibida','green'],missing:['Falta información','gold'],waiting:['Respuesta pendiente','gold'],error:['Error simulado','red']};
function stageRail(c){const keys=['preparacion','solicitada','comparacion','presentada','emision','cerrada'];const idx=keys.indexOf(c.stage);return `<div class="stage-rail" aria-label="Etapas del caso">${keys.map((k,i)=>`<span class="${i===idx?'current':i<idx?'done':''}">${i<idx?icon('check'):''}${STAGES[k]}</span>`).join('')}</div>`;}
function requestRows(c){const reqs=state.requests.filter(r=>r.caseId===c.id);return INSURERS.map(i=>{const r=reqs.find(x=>x.insurerId===i.id);return `<div class="insurer-row"><div class="insurer-mark">${i.short}</div><div><h3>${i.name} ${badge('Simulada')}</h3><p>Canal previsto: ${i.channel} · ${r?e(r.id.slice(0,17)):'Aún no preparada'}</p>${r?badge(...requestLabels[r.status]):badge('Sin solicitud')}<div class="actions">${r?.status==='missing'?button('Aportar soporte de muestra','resolve',r.id,'small','file'):''}${r?.status==='waiting'?button('Simular un error','fail-request',r.id,'small'):''}${r?.status==='error'?button('Reintentar simulación','retry-request',r.id,'small','refresh'):''}${r?button('Ver solicitud','request',r.id,'small'):''}${r?.quote?button('Ver condiciones','quote-doc',r.id,'small'):''}</div></div><div class="insurer-price">${r?.quote?`${money(r.quote.premium)}<small>Por año · COP · ilustrativo</small>`:''}</div></div>`;}).join('');}
function casePage(id,params){const c=caseBy(id);if(!c)return notFound();const cl=client(c.clientId),p=policy(c.policyId),tab=params.get('tab')||'solicitudes',reqs=state.requests.filter(r=>r.caseId===id),qs=reqs.filter(r=>r.quote),auto=p?.product==='Automóvil';return `<a href="#cotizaciones" class="back">${icon('left')}Todos los negocios</a>${pageTitle(c.title,`${cl.name} · ${p?.number||'Sin póliza emitida'} · Caso ficticio`,link('Ver expediente','cliente/'+cl.id,'','users'))}${stageRail(c)}${p&&!p.validated?`<div class="callout">${icon('alert')}<div><strong>Antes de cotizar, confirma la información.</strong><p>La fecha propuesta no coincide con el documento de muestra.</p></div><div class="actions">${link('Revisar documento','incorporar','','file')}</div></div>`:''}${!auto?`<div class="callout info">${icon('info')}<div><strong>Este producto está en fase de definición.</strong><p>Puedes registrar gestiones y revisar el expediente. Los requisitos de cotización se validarán con Víctor. El recorrido automatizado de muestra está en automóvil.</p></div><div class="actions">${link('Ver ejemplo completo','caso/r01')}</div></div>`:''}<nav class="tabs" aria-label="Secciones del caso">${[['solicitudes','Solicitudes'],['comparar',`Comparar propuestas (${qs.length})`],['historial','Historial del caso']].map(([v,t])=>`<a class="tab ${tab===v?'active':''}" href="#caso/${id}?tab=${v}">${t}</a>`).join('')}</nav>${tab==='comparar'?comparison(c,qs):tab==='historial'?`<div class="split"><section><h2>Cada paso conserva su contexto</h2>${timeline(null,id)}</section><aside>${caseSummary(c,p)}${caseNote(c)}</aside></div>`:`<div class="split"><section><div class="section-header"><div><h2>Solicitudes por aseguradora</h2><p>Datos compartidos; requisitos y respuestas por entidad.</p></div></div>${auto?requestRows(c):empty('Requisitos por confirmar','Conserva el expediente y documenta cómo cotiza hoy este producto cada aseguradora.')}<div class="actions section-space">${auto&&reqs.length<INSURERS.length?button(reqs.length?'Añadir entidades pendientes':'Preparar solicitudes','prepare',id,'primary','send'):''}${reqs.some(r=>r.status==='prepared')?button('Simular respuestas','respond',id,'','refresh'):''}${qs.length?link('Comparar propuestas','caso/'+id+'?tab=comparar','','arrow'):''}</div>${note('Los conectores, requisitos, primas y respuestas son ficticios. No representan condiciones ni servicios de una aseguradora real.')}${c.stage==='presentada'?`<div class="decision-stage"><p>La propuesta quedó registrada. Puedes simular la decisión del cliente.</p>${button('Registrar decisión','decision',id,'small')}</div>`:c.stage==='emision'?`<div class="decision-stage"><p>Decisión registrada. Falta evidencia de emisión.</p>${button('Verificar emisión de muestra','issue',id,'small')}</div>`:''}</section><aside>${caseSummary(c,p)}${caseNote(c)}<section class="section-space"><div class="section-header"><h2>Últimas gestiones</h2><a href="#caso/${id}?tab=historial" class="text-link">Ver todas</a></div>${timeline(null,id,3)}</section></aside></div>`}`;}
function caseSummary(c,p){return `<div class="panel panel-pad"><h2 style="font-size:16px">Datos reutilizables</h2><dl class="facts" style="margin-top:20px"><div class="full"><dt>Cliente</dt><dd><a class="text-link" href="#cliente/${c.clientId}">${e(client(c.clientId).name)}</a></dd></div><div><dt>Identificación de muestra</dt><dd>${e(client(c.clientId).identity)}</dd></div><div><dt>Producto</dt><dd>${e(p?.product||c.product||'Por confirmar')}</dd></div>${p?`<div class="full"><dt>Riesgo</dt><dd>${e(p.risk)}</dd></div><div><dt>Vencimiento actual</dt><dd>${date(p.end)}</dd></div><div><dt>Valor de referencia</dt><dd>${money(p.sum)} COP</dd></div>`:''}<div class="full"><dt>Próxima acción</dt><dd>${e(c.next)}</dd></div></dl>${p?`<div class="actions" style="margin-top:18px">${button('Documento fuente','document',p.docId,'small','file')}</div>`:''}</div>`;}
function caseNote(c){return `<form id="case-note" data-id="${c.id}" class="section-space"><label for="case-next">Próxima acción</label><input id="case-next" name="next" value="${e(c.next)}" required maxlength="180"><label for="case-date" style="margin-top:12px">Fecha de gestión</label><input id="case-date" name="due" type="date" value="${c.due}" required><label for="case-note-text" style="margin-top:12px">Registrar una gestión</label><textarea id="case-note-text" name="note" rows="3" placeholder="Qué ocurrió y qué falta por resolver…" required maxlength="2000"></textarea><button type="submit" class="btn" style="margin-top:10px">${icon('save')}Guardar gestión</button><p class="error-message" role="alert"></p></form>`;}
function comparison(c,qs){if(!qs.length)return empty('Aún no hay propuestas para comparar','Prepara solicitudes y simula las respuestas de las entidades.',link('Volver a solicitudes','caso/'+c.id,'primary'));const fields=[['Prima anual · COP',q=>`<strong class="price">${money(q.premium)}</strong><small>Impuestos incluidos · ejemplo</small>`],['Coberturas del ejemplo',q=>e(q.cover)],['Deducible',q=>e(q.deductible)],['Responsabilidad civil',q=>`${money(q.liability)} COP`],['Asistencias',q=>e(q.assistance)],['Exclusiones',q=>e(q.exclusions)],['Validez de la propuesta',q=>date(q.validUntil,{day:'numeric',month:'long',year:'numeric'})],['Fuente',q=>e(q.source)]];return `<div class="section-header"><div><h2>Comparar antes de presentar</h2><p>Valores ilustrativos. Seleccionar una opción solo prepara su presentación.</p></div>${qs.length<2?badge('Falta otra propuesta','gold'):badge('Sin recomendación automática','blue')}</div>${qs.length<2?`<div class="callout">${icon('info')}<p>Hay una sola propuesta. Resuelve el faltante de B para ver las diferencias.</p><div class="actions">${link('Resolver faltante','caso/'+c.id)}</div></div>`:''}<div class="panel table-wrap"><table class="compare"><thead><tr><th>Condición</th>${qs.map(r=>`<th class="${c.selected===r.id?'selected-col':''}">${insurer(r.insurerId).name}<small style="display:block;margin-top:5px">Propuesta simulada</small>${button(c.selected===r.id?'Opción seleccionada':'Elegir para presentar','choose',r.id,`small ${c.selected===r.id?'primary':''}`,c.selected===r.id?'check':'')}</th>`).join('')}</tr></thead><tbody>${fields.map(([label,fn])=>`<tr><td>${label}</td>${qs.map(r=>`<td class="${c.selected===r.id?'selected-col':''}">${fn(r.quote)}</td>`).join('')}</tr>`).join('')}<tr><td>Documento de muestra</td>${qs.map(r=>`<td>${button('Abrir propuesta','quote-doc',r.id,'small','file')}</td>`).join('')}</tr></tbody></table></div><div class="actions section-space">${c.selected?link('Preparar mensaje al cliente','borrador/'+c.id,'primary','mail'):''}${link('Volver a solicitudes','caso/'+c.id)}</div>${note('Las propuestas no son ofertas. El criterio profesional, los requisitos reales y las condiciones particulares siguen pendientes de validación.')}`;}
function documentsPage(params){const q=params.get('q')||'';const docs=state.documents.filter(d=>`${d.title} ${client(d.clientId)?.name}`.toLowerCase().includes(q.toLowerCase()));return `${pageTitle('Archivo de documentos','Cada archivo conserva su cliente, origen y relación con el negocio.',link('Incorporar información','incorporar','primary','layers'))}<form id="filter-documents" class="toolbar"><input name="q" value="${e(q)}" aria-label="Buscar documentos" placeholder="Buscar por cliente o documento"><button class="btn" type="submit">Buscar</button></form><div class="panel"><div class="table-wrap"><table><thead><tr><th>Documento</th><th>Cliente</th><th>Origen</th><th>Estado</th><th></th></tr></thead><tbody>${docs.map(d=>`<tr><td><strong>${e(d.title)}</strong><small>${e(d.type)} · ${date(d.date)}</small></td><td><a class="client-name" href="#cliente/${d.clientId}">${e(client(d.clientId)?.name)}</a></td><td>${e(d.source)}</td><td>${badge(d.status,d.status==='Por revisar'?'gold':'green')}</td><td>${button('Abrir','document',d.id,'small','external')}</td></tr>`).join('')}</tbody></table></div>${!docs.length?empty('Sin coincidencias','Prueba con otro cliente o título.'):''}</div>${note('Los archivos de este ejercicio son documentos HTML de muestra. No son pólizas oficiales ni contienen información real.')}`;}
function intakePage(){const pending=state.intake.filter(i=>i.status==='pending');return `${pageTitle('De la carpeta al expediente','Primero revisar la fuente. Después reutilizar la información.',badge(`${pending.length} revisiones pendientes`,'gold'))}<div class="callout info">${icon('info')}<div><strong>Extracción simulada sobre documentos conocidos</strong><p>Este ejercicio enseña cómo revisar campos, faltantes y duplicados. Todavía no lee documentos arbitrarios ni ejecuta OCR.</p></div></div><div class="panel">${state.intake.map(i=>{const p=policy(i.policyId),cl=client(i.clientId);return `<article class="intake-row">${icon(i.kind==='conflict'?'alert':i.kind==='missing'?'file':'layers','icon-large')}<div><h3>${e(cl.name)} · ${e(p.product)}</h3><p>${e(i.note)}</p>${badge(i.status==='done'?'Revisión resuelta':i.kind==='conflict'?'Fechas distintas':i.kind==='missing'?'Documento faltante':'Posible duplicado',i.status==='done'?'green':'gold')}</div>${button(i.status==='done'?'Ver revisión':'Revisar fuente','review-intake',i.id,i.status==='done'?'small':'primary small','arrow')}</article>`;}).join('')}</div><div class="split section-space"><section><h2>Lo que debe quedar capturado</h2><ul class="plain-list"><li>Cliente y riesgo <span>Identidad y contexto</span></li><li>Póliza y vigencia <span>Número, fechas y versión</span></li><li>Documento fuente <span>Origen verificable</span></li><li>Estado de revisión <span>Confirmado o pendiente</span></li><li>Próxima gestión <span>Acción y fecha</span></li></ul></section><section><h2>Sin borrar la historia</h2><p class="intro-prose" style="margin-top:15px">Un anexo, una copia o una renovación no son lo mismo. El registro conserva las relaciones entre documentos y vigencias. Las coincidencias ambiguas se revisan antes de fusionar información.</p>${link('Ver historia de Elena','caso/r01?tab=historial','','arrow')}</section></div>`;}
function messagesPage(params){const caseId=params.get('caso');const list=state.messages.filter(m=>!caseId||m.caseId===caseId);const selected=list.find(m=>m.id===params.get('id'))||list[0];return `${pageTitle('Conversaciones con contexto','Cliente y aseguradora, vinculados al mismo negocio.',button('Preparar mensaje','compose','','primary','mail'))}<form class="toolbar" id="filter-messages"><select name="caso" aria-label="Filtrar comunicaciones por negocio"><option value="">Todos los negocios</option>${state.cases.map(c=>`<option value="${c.id}" ${c.id===caseId?'selected':''}>${e(client(c.clientId).name)} · ${e(c.title)}</option>`).join('')}</select><button class="btn" type="submit">Filtrar</button><span class="muted">${list.length} mensajes ficticios</span></form><div class="panel">${list.length?`<div class="message-layout"><div class="message-list" aria-label="Mensajes">${list.map(m=>`<button class="${m.id===selected.id?'active':''}" data-action="message" data-id="${m.id}" data-case="${e(caseId||'')}"><div style="display:flex;justify-content:space-between;gap:10px"><small>${e(client(m.clientId)?.name||'Agencia demo')}</small><small>${date(m.at)}</small></div><h3>${e(m.subject)}</h3><p>${e(m.body)}</p></button>`).join('')}</div><article class="message-view"><div class="actions">${badge(selected.direction,'blue')}${badge(selected.status,selected.direction==='Entrante'?'green':'gold')}</div><h2>${e(selected.subject)}</h2><div class="message-meta">${e(selected.direction==='Entrante'?'Para':'Destinatario')}: ${e(selected.recipient)}<br>Canal: ${e(selected.channel)} · ${date(selected.at,{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})}</div><div class="message-body">${e(selected.body)}</div><div class="actions section-space">${link('Abrir caso','caso/'+selected.caseId,'','arrow')}${link('Ver cliente','cliente/'+selected.clientId)}</div></article></div>`:empty('Sin comunicaciones en este filtro','Prepara un borrador o simula la respuesta de una aseguradora.',button('Preparar mensaje','compose'))}</div>`;}
function draftPage(id,params){const c=caseBy(id);if(!c)return notFound();const template=params.get('tipo')||'propuesta';let body=state.drafts[draftKey(id,template)]?.body||'';if(!body){try{body=template==='propuesta'?customerDraft(state,id):templateText(template,c);}catch{return `${pageTitle('Preparar comunicación','Primero elige la información que vas a presentar.')}<div class="callout">${icon('info')}<p>Selecciona una propuesta antes de preparar su presentación al cliente.</p></div>${link('Comparar propuestas','caso/'+id+'?tab=comparar','primary')}`;}}return `<a href="#caso/${id}" class="back">${icon('left')}Volver al caso</a>${pageTitle('Un mensaje, con toda la información.',`${client(c.clientId).name} · ${c.title}`)}<div class="split"><form id="draft-form" data-id="${id}" data-template="${e(template)}"><label for="draft-recipient">Destinatario ficticio</label><input id="draft-recipient" value="${e(template==='seguimiento'?'cotizaciones@aseguradora-demo.example.com':client(c.clientId).email)}" readonly><label for="draft-body" style="margin-top:20px">Borrador editable</label><textarea name="body" id="draft-body" rows="18" required maxlength="10000">${e(body)}</textarea><p class="page-note">El texto se conserva al cambiar de sección. Cada plantilla mantiene su propio borrador.</p><div class="actions" style="margin-top:16px"><button class="btn primary" type="submit">${icon('send')}Registrar envío simulado</button>${button('Guardar borrador','save-draft',id,'','save')}</div><p class="error-message" role="alert"></p></form><aside><div class="callout info">${icon('info')}<div><strong>Este mensaje se queda en el demo.</strong><p>Registrar el envío actualiza el historial. No se abre correo ni WhatsApp y no se transmite información.</p></div></div>${caseSummary(c,policy(c.policyId))}<section class="section-space"><h2 style="font-size:16px">Otras comunicaciones</h2><ul class="plain-list">${[['faltantes','Pedir documentos al cliente'],['seguimiento','Dar seguimiento a aseguradora'],['renovacion','Avisar renovación próxima']].map(([v,t])=>`<li><a class="text-link" href="#borrador/${id}?tipo=${v}" data-clear-draft="${id}">${t}${icon('arrow')}</a></li>`).join('')}</ul></section></aside></div>`;}
function templateText(type,c){const cl=client(c.clientId),p=policy(c.policyId);if(type==='faltantes')return `Hola, ${cl.name.split(' ')[0]}:\n\nPara continuar con ${c.title.toLowerCase()}, necesitamos confirmar los documentos indicados en el expediente: [revisar lista de faltantes].\n\nPor favor revisemos el soporte y el canal adecuado para aportarlo.\n\nBorrador ficticio para revisar; no enviado.`;if(type==='seguimiento')return `Hola, equipo de la aseguradora simulada:\n\nDamos seguimiento al caso ${c.id}, de ${cl.name}, identificación ficticia ${cl.identity}.\n\n¿Nos pueden confirmar el estado de la solicitud y si necesitan información adicional?\n\nReferencia: ${p?.number||'Negocio nuevo'}. Este texto es un ejemplo ficticio; no se ha transmitido.`;return `Hola, ${cl.name.split(' ')[0]}:\n\n${p?`Tu póliza de ${p.product.toLowerCase()} tiene registrado un vencimiento el ${date(p.end,{day:'numeric',month:'long',year:'numeric'})}.`:'Estamos revisando tu solicitud.'}\n\nQueremos revisar tus necesidades y preparar las opciones con anticipación. ¿Ha cambiado algo que debamos tener en cuenta?\n\nMensaje ficticio; no confirma cobertura ni renovación.`;}
function opportunitiesPage(){return `${pageTitle('El próximo negocio también empieza aquí.','Un lead entra al mismo circuito de información y seguimiento.',button('Probar formulario','lead-form','','primary','plus'))}<div class="flow"><div class="flow-node">Solicitud<small>Origen y necesidad</small></div>${icon('arrow')}<div class="flow-node">Oportunidad<small>Contacto y seguimiento</small></div>${icon('arrow')}<div class="flow-node">Cotización<small>Expediente reutilizable</small></div>${icon('arrow')}<div class="flow-node">Cliente<small>Servicio y renovación</small></div></div><div class="panel">${state.leads.length?`<div class="table-wrap"><table><thead><tr><th>Solicitud</th><th>Producto</th><th>Origen</th><th>Estado</th><th></th></tr></thead><tbody>${state.leads.map(l=>`<tr><td><strong>${e(l.name)}</strong><small>${e(l.email)}</small></td><td>${e(l.product)}</td><td>${e(l.source)}</td><td>${badge(l.status,l.caseId?'green':'gold')}</td><td>${l.caseId?link('Abrir caso','caso/'+l.caseId,'small'):button('Abrir seguimiento','convert-lead',l.id,'small')}</td></tr>`).join('')}</tbody></table></div>`:empty('Prueba la entrada de un nuevo negocio','Crea una solicitud ficticia y observa cómo se convierte en un caso sin capturar de nuevo los datos.',button('Crear solicitud de muestra','lead-form','','primary','plus'))}</div><div class="split section-space"><section><h2>Antes de invertir en captación</h2><ul class="plain-list"><li>Elegir producto y público <span>Por validar con la familia</span></li><li>Definir un mensaje comprobable <span>Sin promesas de cobertura</span></li><li>Registrar el origen <span>Referido, web o campaña</span></li><li>Medir hasta emisión <span>Además de visitas y consultas</span></li></ul></section><section><h2>El portal del cliente, después</h2><p class="intro-prose" style="margin-top:15px">Consulta de pólizas, documentos aprobados, vigencias y solicitudes, sobre el mismo registro central. La identidad, los permisos y los canales reales deben resolverse antes de usar información privada.</p>${link('Ver mapa de evolución','conexiones','','arrow')}</section></div>`;}
const integrationQuestions=['¿Cómo llega una solicitud nueva y cómo detecta una renovación?','¿Qué información consulta en la carpeta y qué vuelve a pedir?','¿Qué datos y adjuntos envía a cada aseguradora?','¿Qué correo estándar utiliza para pedir una cotización?','¿En qué portales entra y qué pasos repite?','¿Cómo recibe la respuesta, sus condiciones y su vigencia?','¿Qué faltantes suelen devolverle las aseguradoras?','¿Cómo compara las opciones antes de recomendarlas?','¿Qué mensaje envía al cliente y cómo recibe la decisión?','¿Qué evidencia confirma emisión, entrega y próxima renovación?','¿Cuándo hace seguimiento, lo detiene o escala el caso?','¿Qué excepciones frecuentes no caben en este recorrido?'];
function connectionsPage(){return `${pageTitle('Conectar sin perder el hilo.','El expediente es común. El canal y los requisitos cambian por entidad.')}<div class="flow"><div class="flow-node">Carpetas y mensajes<small>Fuentes autorizadas</small></div>${icon('arrow')}<div class="flow-node">Expediente central<small>Datos revisados</small></div>${icon('arrow')}<div class="flow-node">Solicitud estructurada<small>Por producto y entidad</small></div>${icon('arrow')}<div class="flow-node">Canal real<small>Por confirmar</small></div></div><div class="section-header section-space"><h2>Mapa inicial de aseguradoras</h2>${badge('Sin conexiones activas','gold')}</div><div class="panel table-wrap"><table class="matrix-table"><thead><tr><th>Entidad mencionada</th><th>Canal actual</th><th>Datos y documentos</th><th>API / convenio</th><th>Qué validar</th></tr></thead><tbody>${['AXA Colpatria','Seguros del Estado','Allianz','MAPFRE'].map(name=>`<tr><td><strong>${name}</strong></td><td>Por confirmar</td><td>Por producto</td><td>${badge('No verificado')}</td><td>Recorrido, requisitos y acceso autorizado</td></tr>`).join('')}</tbody></table></div><div class="split section-space"><section><h2>Cuatro caminos posibles</h2><ul class="plain-list"><li><div><strong>Correo</strong><p class="muted">Preparar texto y adjuntos; relacionar respuestas.</p></div>${badge('Investigar')}</li><li><div><strong>Portal de aseguradora</strong><p class="muted">Preparar datos y evaluar captura asistida permitida.</p></div>${badge('Investigar')}</li><li><div><strong>API o convenio</strong><p class="muted">Confirmar disponibilidad, acceso y condiciones.</p></div>${badge('No confirmado')}</li><li><div><strong>Ejecutivo o intermediario</strong><p class="muted">Estandarizar solicitud y seguimiento.</p></div>${badge('Investigar')}</li></ul></section><section><h2>Lo que ya simula el ejercicio</h2><ul class="checklist section-space"><li>${icon('check')}<div>Una solicitud por entidad<small>Mismo expediente, referencias separadas.</small></div></li><li>${icon('check')}<div>Respuestas asíncronas<small>Propuesta, faltante, espera y error.</small></div></li><li>${icon('check')}<div>Historial y control de duplicados<small>Reintentar no crea otro caso.</small></div></li><li>${icon('check')}<div>Comparación con fuentes<small>Sin confundir precio con recomendación.</small></div></li></ul>${link('Explorar mesa de cotización','caso/r01','','arrow')}</section></div>${note('No se ha verificado ninguna API o permiso de automatización. Los adaptadores A/B/C no corresponden a estas entidades reales.')}`;}
function meetingPage(params){const tab=params.get('tab')||'decisiones';return `${pageTitle('Una conversación sobre algo concreto.','Miércoles 21 de octubre · Probar, cuestionar y ajustar la dirección.',button('Exportar notas y datos','export','','','download'))}<nav class="tabs" aria-label="Preparar reunión">${[['decisiones','Observaciones de la familia'],['preguntas','Qué preguntar a Víctor'],['alcance','Qué funciona y qué es simulado']].map(([v,t])=>`<a class="tab ${v===tab?'active':''}" href="#reunion?tab=${v}">${t}</a>`).join('')}</nav>${tab==='preguntas'?`<p class="intro-prose">Reconstruyan una renovación y una cotización nueva. Estas respuestas aclaran canales, datos repetidos y excepciones. No hace falta incorporar información personal.</p><form id="interview-form"><div class="question-list">${integrationQuestions.map((q,i)=>`<div class="question"><label for="answer-${i}">${i+1}. ${e(q)}</label><textarea id="answer-${i}" name="q${i}" rows="2" placeholder="Describir el procedimiento y sus variantes…">${e(state.interview['q'+i]||'')}</textarea></div>`).join('')}</div><div class="form-actions"><button class="btn primary" type="submit">${icon('save')}Guardar respuestas</button></div></form>`:tab==='alcance'?scopeContent():`<div class="split"><section><h2>Registrar un ajuste al diseño</h2><p class="intro-prose" style="margin-top:10px">Qué falta, dónde se conectaría una fuente o qué paso debería cambiar. La asignación de funciones familiares queda para su discusión.</p><form id="observation-form"><div class="form-grid"><div><label for="ob-area">Parte del recorrido</label><select id="ob-area" name="area">${['Expedientes','Documentos','Cotización','Comunicaciones','Conexiones','Crecimiento','Otro'].map(x=>`<option>${x}</option>`).join('')}</select></div><div><label for="ob-type">Tipo de observación</label><select id="ob-type" name="type"><option>Ajuste propuesto</option><option>Pregunta por resolver</option><option>Supuesto confirmado</option><option>Supuesto descartado</option></select></div><div class="full"><label for="ob-text">¿Qué cambiaríamos o validaríamos?</label><textarea id="ob-text" name="text" required maxlength="3000" rows="5" placeholder="Por ejemplo: esta aseguradora pide la ficha por correo, no por portal…"></textarea></div></div><div class="form-actions"><button class="btn primary" type="submit">${icon('plus')}Guardar observación</button></div><p class="error-message" role="alert"></p></form></section><section><div class="section-header"><h2>Notas de trabajo</h2><span class="muted">${state.observations.length}</span></div>${state.observations.length?state.observations.map(o=>`<article class="observation">${badge(o.area)} <small>${e(o.type)}</small><p>${e(o.text)}</p><small>${date(o.at,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</small></article>`).join(''):empty('Las decisiones empiezan con una observación','Prueben el recorrido y anoten aquí los ajustes. No hay funciones familiares asignadas.')}</section></div>`}`;}
function scopeContent(){return `<div class="split"><section><h2>Funciona dentro del navegador</h2><ul class="checklist section-space">${['Consulta y edición de expedientes ficticios','Registro de gestiones y próximos pasos','Validación de los ejemplos documentales','Estados por solicitud y prevención de duplicados','Comparación y borradores editables','Entrada de leads ficticios y seguimiento','Guardado local, exportación y restablecimiento'].map(t=>`<li>${icon('check')}${t}</li>`).join('')}</ul><h2 class="section-space">Se simula explícitamente</h2><ul class="plain-list"><li>Extracción de los documentos conocidos</li><li>Solicitud y respuesta de aseguradoras A/B/C</li><li>Envío de comunicaciones y emisión</li></ul></section><section><h2>Requiere información y trabajo posterior</h2><ul class="plain-list"><li>Canales y requisitos reales por aseguradora</li><li>Disponibilidad y condiciones de APIs</li><li>Ingreso de correo y WhatsApp autorizado</li><li>OCR y extracción de archivos arbitrarios</li><li>Identidad, permisos y seguridad para datos reales</li><li>Base de datos compartida y acceso multiusuario</li><li>Portal del cliente y publicación comercial</li></ul><div class="callout info section-space">${icon('info')}<div><strong>Persistencia de este ejercicio</strong><p>Los cambios se guardan solo en este navegador y origen. Exporta una copia para conservar las notas o trasladarlas. No es una base de datos compartida.</p></div></div></section></div>`;}
function notFound(){return `${pageTitle('No encontramos este registro.','El enlace puede pertenecer a un ejercicio que ya se restableció.')}${link('Volver a mi día','inicio','primary')}`;}
function render(){const {parts,params}=route();let content,key=parts[0];if(key==='sitio'){const page=commercialRoute(parts,params,{state,e,icon,button,link,money,date,docRows});document.getElementById('app').innerHTML=page.html;document.title='Arias · '+page.title;return;}switch(key){case'inicio':content=dashboard();break;case'clientes':content=clientsPage(params);break;case'cliente':content=clientPage(parts[1]);key='clientes';break;case'polizas':content=policiesPage(params);break;case'cotizaciones':content=casesPage();break;case'caso':content=casePage(parts[1],params);key='cotizaciones';break;case'documentos':content=documentsPage(params);break;case'incorporar':content=intakePage();break;case'mensajes':content=messagesPage(params);break;case'borrador':content=draftPage(parts[1],params);key='mensajes';break;case'oportunidades':content=opportunitiesPage();break;case'conexiones':content=connectionsPage();break;case'reunion':content=meetingPage(params);break;default:content=notFound();}document.getElementById('app').innerHTML=shell(content,key);document.title=`Arias · ${({inicio:'Mi día',clientes:'Clientes',polizas:'Pólizas',cotizaciones:'Mesa de cotización',mensajes:'Comunicaciones',documentos:'Documentos',incorporar:'Incorporar información',oportunidades:'Nuevos negocios',conexiones:'Conexiones futuras',reunion:'Reunión familiar'})[key]||'Mesa de seguros'}`;}

const dialog=document.getElementById('dialog');let returnFocus;
function generatedDocument(d){const cl=client(d.clientId),p=policy(d.policyId);const rows=[['Cliente ficticio',cl.name],['Identificación',cl.identity],['Tipo de documento',d.type],['Póliza relacionada',p?.number||'Por confirmar'],['Riesgo',p?.risk||'Por confirmar'],['Desde',p?date(p.start,{day:'numeric',month:'long',year:'numeric'}):'Por confirmar'],['Hasta',p?date(p.end,{day:'numeric',month:'long',year:'numeric'}):'Por confirmar'],['Prima anual ilustrativa',p?money(p.premium)+' COP':'No aplica'],['Entidad simulada',p?.insurer||'No aplica'],['Origen',d.source]];return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Documento ficticio</title><style>body{font:14px/1.7 Arial,sans-serif;color:#21323a;padding:30px;max-width:700px;margin:auto}h1{font:32px Georgia,serif;color:#142d3a}small{color:#a14c38;font-weight:bold}dl{display:grid;grid-template-columns:1fr 1fr;gap:20px;border-top:1px solid #dfe4e2;padding-top:20px}dt{font-size:11px;color:#626e73}dd{margin:4px 0 0;font-weight:bold}footer{font-size:11px;margin-top:25px;border-top:1px solid #dfe4e2;padding-top:16px}@media(max-width:450px){body{padding:20px}dl{grid-template-columns:1fr}}</style></head><body><small>DOCUMENTO FICTICIO · SIN VALIDEZ CONTRACTUAL</small><h1>${e(d.title)}</h1><dl>${rows.map(([k,v])=>`<div><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`).join('')}</dl><p>${d.type==='Soporte adicional ficticio'?'En este escenario, el cliente declara un uso particular del vehículo. Es una declaración de muestra, sin firma ni efectos reales.':'La nueva vigencia está vinculada a la anterior dentro del demo. No se emitió un seguro real.'}</p><footer>Generado exclusivamente para el ejercicio Arias. No acredita identidad, propiedad, aceptación, emisión ni cobertura.</footer></body></html>`;}
function downloadText(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(title,sub,body,wide=false){returnFocus=document.activeElement;dialog.classList.toggle('wide',wide);document.getElementById('dialog-content').innerHTML=`<div class="dialog-head"><div><h2 id="dialog-title">${e(title)}</h2>${sub?`<p>${e(sub)}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="Cerrar">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;dialog.showModal();}
function close(){dialog.close();if(returnFocus?.isConnected)returnFocus.focus();}
function draftKey(caseId,template){return `${caseId}:${template}`;}
function saveCurrentDraft(){const f=document.getElementById('draft-form');if(!f||f.dataset.sent==='true')return;const body=document.getElementById('draft-body')?.value;if(body===undefined)return;state.drafts[draftKey(f.dataset.id,f.dataset.template)]={body,template:f.dataset.template};save();}
dialog.addEventListener('click',ev=>{if(ev.target===dialog){const r=dialog.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)close();}});
function documentModal(id){const d=state.documents.find(x=>x.id===id);if(!d)return toast('No encontramos este documento.',true);modal(d.title,`${client(d.clientId)?.name} · ${d.type} · Información ficticia`,`<iframe title="Documento de muestra: ${e(d.title)}" ${d.generated?`srcdoc="${e(generatedDocument(d))}"`:`src="${e(d.file)}"`} sandbox></iframe><div class="actions section-space">${d.generated?button('Descargar muestra HTML','download-document',d.id,'','download'):`<a class="btn" href="${e(d.file)}" download>${icon('download')}Descargar muestra HTML</a>`}${button('Cerrar documento','close')}</div>`,true);}
function intakeModal(id){const i=state.intake.find(x=>x.id===id),p=policy(i.policyId),c=client(i.clientId);if(i.status==='done'){modal('Revisión completada',c.name,`<div class="callout info">${icon('check')}<p>La revisión de este ejemplo ya está resuelta. La historia conserva la validación.</p></div>${link('Abrir expediente','cliente/'+c.id,'primary')}`);return;}modal(i.kind==='conflict'?'Confirmar la vigencia':i.kind==='missing'?'Completar un soporte':'Revisar posible duplicado',`${c.name} · ${p.number}`,`<div class="split"><div class="source-sheet"><span class="stamp">DOCUMENTO FICTICIO</span><h3>Carátula de muestra</h3><dl><dt>Cliente</dt><dd>${e(c.name)}</dd><dt>Póliza</dt><dd>${p.number}</dd><dt>Producto</dt><dd>${e(p.product)}</dd><dt>Vigencia desde</dt><dd>${date(p.start,{day:'numeric',month:'long',year:'numeric'})}</dd><dt>Vigencia hasta</dt><dd><strong>${date(p.end,{day:'numeric',month:'long',year:'numeric'})}</strong></dd><dt>Fuente</dt><dd>Carpeta / ${c.identity} / ${p.id}.html</dd></dl><a class="text-link" href="documentos/${p.id}.html" target="_blank" rel="noopener">Abrir archivo completo ${icon('external')}</a></div><form id="intake-form" data-id="${i.id}"><h3>${i.kind==='conflict'?'Propuesta de extracción':i.kind==='missing'?'Información incompleta':'Copia detectada'}</h3><p class="intro-prose" style="margin-top:12px">${e(i.note)}</p>${i.kind==='conflict'?`<label for="confirm-expiry">Fecha final a confirmar</label><input name="end" id="confirm-expiry" type="date" value="${i.suggestedEnd}" required><p class="page-note">Corrige el dato según la carátula. La propuesta no se confirma automáticamente.</p>`:i.kind==='missing'?`<p>Se incorporará una ficha ficticia de riesgos y se conservará el registro de su origen.</p>`:`<p>El número y la vigencia coinciden con una póliza existente. Se descartará la copia propuesta sin eliminar el original.</p>`}<div class="form-actions"><button class="btn primary" type="submit">${icon('check')}${i.kind==='duplicate'?'Conservar una sola póliza':i.kind==='missing'?'Incorporar soporte de muestra':'Confirmar información'}</button></div><p class="error-message" role="alert"></p></form></div>`,true);}
function prepareModal(id){const c=caseBy(id),p=policy(c.policyId);if(!p?.validated)return toast('Confirma la vigencia del expediente antes de preparar solicitudes.',true);if(p.product!=='Automóvil')return toast('El conector de muestra está preparado para automóvil.',true);modal('Preparar una solicitud, reutilizar los datos.',`${client(c.clientId).name} · ${p.product} · Sin envío externo`,`<form id="prepare-form" data-id="${id}"><dl class="facts"><div><dt>Identificación ficticia</dt><dd>${e(client(c.clientId).identity)}</dd></div><div><dt>Valor de referencia</dt><dd>${money(p.sum)} COP</dd></div><div class="full"><dt>Riesgo declarado</dt><dd>${e(p.risk)}</dd></div></dl><h3 class="section-space">Entidades del escenario</h3>${INSURERS.map(i=>{const exists=state.requests.some(r=>r.caseId===id&&r.insurerId===i.id);return `<label class="request-check"><input type="checkbox" name="insurer" value="${i.id}" ${exists?'disabled':'checked'}><span><strong>${i.name} · simulada</strong><small>Canal previsto: ${i.channel}</small></span>${exists?badge('Ya preparada','green'):badge('Incluir','blue')}</label>`;}).join('')}<p class="page-note">Se adjuntan referencias a ${requestDocuments(state,c,p).length} documentos pertinentes de muestra. Cada entidad conserva su solicitud y estado.</p><div class="form-actions"><button class="btn primary" type="submit">${icon('send')}Preparar solicitudes simuladas</button></div><p class="error-message" role="alert"></p></form>`);}
function requestModal(id){const r=state.requests.find(x=>x.id===id),i=insurer(r.insurerId),cl=client(r.clientId);modal('Solicitud de cotización',`${i.name} · Simulada · ${requestLabels[r.status][0]}`,`<dl class="facts"><div class="full"><dt>Referencia interna</dt><dd style="overflow-wrap:anywhere">${e(r.id)}</dd></div><div><dt>Cliente</dt><dd>${e(cl.name)}</dd></div><div><dt>Identificación ficticia</dt><dd>${e(cl.identity)}</dd></div><div class="full"><dt>Riesgo</dt><dd>${e(r.payload.risk)}</dd></div><div><dt>Desde</dt><dd>${date(r.payload.start)}</dd></div><div><dt>Período</dt><dd>${r.payload.period}</dd></div><div><dt>Canal previsto</dt><dd>${i.channel}</dd></div><div><dt>Intentos</dt><dd>${r.attempt}</dd></div></dl><h3 class="section-space">Adjuntos referenciados</h3>${docRows(state.documents.filter(d=>r.attachments.includes(d.id)))}${note('Este paquete está preparado dentro del demo. No se transmitió a ninguna entidad.')}`);}
function quoteModal(id){const r=state.requests.find(x=>x.id===id);if(!r?.quote)return;const q=r.quote;modal('Propuesta de muestra',`${insurer(r.insurerId).name} · No constituye oferta`,`<div class="source-sheet"><span class="stamp">SIMULACIÓN · SIN VALIDEZ CONTRACTUAL</span><h3>Renovación de automóvil</h3><dl class="facts"><div><dt>Cliente ficticio</dt><dd>${e(client(r.clientId).name)}</dd></div><div><dt>Prima anual · COP</dt><dd>${money(q.premium)}</dd></div><div><dt>Impuestos</dt><dd>Incluidos en este ejemplo</dd></div><div><dt>Vigencia de oferta</dt><dd>${date(q.validUntil)}</dd></div><div class="full"><dt>Coberturas</dt><dd>${e(q.cover)}</dd></div><div><dt>Deducible</dt><dd>${e(q.deductible)}</dd></div><div><dt>Límite de RC · COP</dt><dd>${money(q.liability)}</dd></div><div class="full"><dt>Asistencias</dt><dd>${e(q.assistance)}</dd></div><div class="full"><dt>Exclusiones</dt><dd>${e(q.exclusions)}</dd></div></dl></div>`);}
function clientModal(id){const c=client(id);modal(c?'Editar expediente ficticio':'Crear cliente ficticio','Usa exclusivamente información inventada para este ejercicio.',`<form id="client-form" data-id="${e(id||'')}"><div class="form-grid"><div class="full"><label for="cl-name">Nombre de muestra</label><input id="cl-name" name="name" value="${e(c?.name||'')}" required maxlength="100"></div><div><label for="cl-email">Correo ficticio</label><input id="cl-email" name="email" type="email" value="${e(c?.email||'')}" placeholder="cliente@example.com" required></div><div><label for="cl-city">Ciudad</label><input id="cl-city" name="city" value="${e(c?.city||'Bogotá')}" required maxlength="80"></div><div><label for="cl-type">Tipo</label><select id="cl-type" name="type"><option ${c?.type==='Persona'?'selected':''}>Persona</option><option ${c?.type==='Empresa'?'selected':''}>Empresa</option></select></div><div><label for="cl-channel">Canal preferido</label><select id="cl-channel" name="channel"><option ${c?.channel==='Correo'?'selected':''}>Correo</option><option ${c?.channel==='WhatsApp'?'selected':''}>WhatsApp</option></select></div><div class="full"><label for="cl-note">Contexto</label><textarea id="cl-note" name="note" rows="3" maxlength="2000">${e(c?.note||'')}</textarea></div></div><div class="form-actions"><button class="btn primary" type="submit">${icon('save')}Guardar expediente</button></div><p class="error-message" role="alert"></p></form>`);}
function newCaseModal(clientId){modal('Abrir un negocio','Crear el caso conserva el vínculo con el cliente y su información.',`<form id="new-case-form"><div class="form-grid"><div class="full"><label for="nc-client">Cliente del ejercicio</label><select name="clientId" id="nc-client">${state.clients.map(c=>`<option value="${c.id}" ${c.id===clientId?'selected':''}>${e(c.name)}</option>`).join('')}</select></div><div><label for="nc-type">Tipo de caso</label><select name="type" id="nc-type"><option>Renovación</option><option>Negocio nuevo</option><option>Solicitud de servicio</option></select></div><div><label for="nc-product">Producto</label><select name="product" id="nc-product">${PRODUCTS.map(p=>`<option>${p}</option>`).join('')}</select></div><div class="full"><label for="nc-next">Próxima acción</label><input name="next" id="nc-next" value="Confirmar necesidad y documentos" required maxlength="180"></div><div><label for="nc-date">Fecha de gestión</label><input name="due" id="nc-date" type="date" value="${REFERENCE_DATE}" required></div></div><div class="form-actions"><button class="btn primary" type="submit">${icon('plus')}Crear caso ficticio</button></div><p class="error-message" role="alert"></p></form>`);}
function leadModal(productSlug){modal('Así entra una nueva oportunidad.','Formulario de prueba conectado a la mesa de trabajo.',`<div class="split"><div class="lead-preview"><div class="brand"><img class="app-monogram" src="images/arias-monogram.svg" alt="" width="42" height="42"><span class="app-wordmark">Asesores de Seguros<small>Arias &amp; Cía. Ltda.</small></span></div><h2>Protección que empieza por escucharte.</h2><p>Cuéntanos qué necesitas revisar. La solicitud se convierte en una oportunidad dentro del mismo expediente.</p><p style="margin-top:24px">Ejercicio ficticio · Sin cotización real</p></div><form id="lead-form" class="lead-form"><h2>Solicitar asesoría de muestra</h2><div class="field-group"><label for="lead-name">Nombre ficticio</label><input id="lead-name" name="name" value="Mariana del Valle" required maxlength="100"></div><div class="field-group"><label for="lead-email">Correo de muestra</label><input id="lead-email" name="email" type="email" value="mariana@example.com" required></div><div class="field-group"><label for="lead-product">¿Qué quieres proteger?</label><select id="lead-product" name="product">${PRODUCTS.map(p=>`<option ${({'vida':'Vida','salud':'Salud y prepagada','auto':'Automóvil','hogar':'Hogar','empresarial':'Empresarial','arl':'Laborales y colectivos','exequial':'Exequial','viajes':'Viajes'})[productSlug]===p?'selected':''}>${p}</option>`).join('')}</select></div><div class="field-group"><label for="lead-source">Origen del ejemplo</label><select id="lead-source" name="source"><option>Referido</option><option>Página web</option><option>Campaña de muestra</option></select></div><div class="field-group"><label for="lead-need">Necesidad breve</label><textarea id="lead-need" name="need" rows="2" maxlength="1000">Quiero revisar opciones antes de renovar.</textarea></div><label class="request-check"><input name="fictional" type="checkbox" required><span>Confirmo que estos datos son ficticios.</span></label><button class="btn primary" type="submit">Crear solicitud de prueba ${icon('arrow')}</button><p class="error-message" role="alert"></p></form></div>`,true);}
function guideModal(){const progress=[policy('p01').validated,state.requests.some(r=>r.caseId==='r01'),state.requests.filter(r=>r.caseId==='r01'&&r.quote).length>=2,!!caseBy('r01').selected,state.messages.some(m=>m.caseId==='r01'&&m.subject==='Opciones para tu renovación'),state.leads.length>0];const steps=[['Confirmar la información','Resolver la diferencia de fechas contra la carátula.','incorporar'],['Preparar solicitudes','Reutilizar el expediente en tres entidades simuladas.','caso/r01'],['Recibir y comparar','Resolver el faltante de B y revisar las condiciones.','caso/r01?tab=comparar'],['Preparar una propuesta','Elegir una opción sin aceptar ningún contrato.','caso/r01?tab=comparar'],['Comunicar y seguir','Editar el mensaje y registrar un envío simulado.','borrador/r01'],['Conectar el crecimiento','Crear un lead y abrir su seguimiento.','oportunidades']];modal('El recorrido de la reunión','Un caso completo en 12–15 minutos. Puedes volver a esta guía cuando quieras.',`<p class="muted">${progress.filter(Boolean).length} de ${steps.length} hitos explorados · Todo es ficticio</p><div class="guide-progress"><span style="width:${progress.filter(Boolean).length/steps.length*100}%"></span></div>${steps.map(([t,d,h],i)=>`<div class="guide-step"><span>${progress[i]?icon('check'):i+1}</span><div><h3>${t}</h3><p>${d}</p></div>${link('Abrir',h,'small')}</div>`).join('')}<div class="actions section-space">${link('Anotar ajustes de la familia','reunion','','note')}${button('Restablecer el ejercicio','reset','','ghost','refresh')}</div>`);}
function exportData(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),referenceDate:REFERENCE_DATE,fictional:true,...state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='arias-ejercicio-ficticio.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Copia del ejercicio exportada, incluidas las notas de la reunión.');}

document.addEventListener('click',ev=>{const clear=ev.target.closest('[data-clear-draft]');if(clear){saveCurrentDraft();}const anchor=ev.target.closest('a[href^="#"]');if(anchor?.getAttribute('href')==='#main'){ev.preventDefault();document.getElementById('main').focus();return;}if(anchor&&dialog.open){close();}const b=ev.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;try{switch(action){case'close':close();break;case'guide':if(dialog.open)close();guideModal();break;case'export':exportData();break;case'reset':if(dialog.open)close();modal('Restablecer el ejercicio','Se borrarán solo los cambios de este demo guardados en este navegador.',`<p>Se recuperarán los clientes, documentos y casos ficticios iniciales. Exporta primero si quieres conservar las notas de la reunión.</p><div class="form-actions">${button('Cancelar','close')}${button('Restablecer datos ficticios','confirm-reset','','danger','refresh')}</div>`);break;case'confirm-reset':state=seedData();save();close();location.hash='inicio';render();toast('Ejercicio restablecido. Puedes volver a presentar el recorrido.');break;case'download-document':{const d=state.documents.find(x=>x.id===id);downloadText(generatedDocument(d),'arias-documento-ficticio.html','text/html');break;}case'document':if(dialog.open)close();documentModal(id);break;case'review-intake':intakeModal(id);break;case'prepare':prepareModal(id);break;case'respond':{const n=simulateResponses(state,id);save();render();toast(n?'Respuestas simuladas. Revisa propuestas, faltantes y pendientes.':'Las respuestas ya estaban registradas.');break;}case'resolve':resolveRequest(state,id);save();render();toast('Soporte ficticio incorporado. B respondió con una propuesta simulada.');break;case'choose':{const r=state.requests.find(x=>x.id===id);chooseQuote(state,r.caseId,id);save();render();toast('Opción elegida para preparar el mensaje.');break;}case'request':requestModal(id);break;case'quote-doc':quoteModal(id);break;case'edit-client':clientModal(id);break;case'new-client':clientModal();break;case'new-case':newCaseModal(id);break;case'lead-form':leadModal(id);break;case'convert-lead':{const cs=convertLead(state,id);save();location.hash='caso/'+cs;toast('Datos reutilizados. Ya puedes seguir el nuevo negocio.');break;}case'message':location.hash=`mensajes?${new URLSearchParams({...(b.dataset.case?{caso:b.dataset.case}:{}),id})}`;break;case'compose':modal('Elegir una comunicación','El borrador toma información del caso, sin envíos externos.',`<form id="compose-form"><label for="compose-case">Negocio</label><select name="caseId" id="compose-case">${state.cases.map(c=>`<option value="${c.id}">${e(client(c.clientId).name)} · ${e(c.title)}</option>`).join('')}</select><label for="compose-type" style="margin-top:17px">Plantilla</label><select name="template" id="compose-type"><option value="renovacion">Aviso de renovación</option><option value="faltantes">Pedir documentos al cliente</option><option value="seguimiento">Seguimiento a aseguradora</option><option value="propuesta">Presentar propuesta al cliente</option></select><div class="form-actions"><button class="btn primary" type="submit">Preparar borrador</button></div></form>`);break;case'save-draft':saveCurrentDraft();toast('Borrador guardado en este navegador.');break;case'fail-request':{const r=state.requests.find(x=>x.id===id);r.status='error';event(state,r.caseId,'Error de conexión simulado','No se obtuvo respuesta. La solicitud conserva su ID para reintentar.');save();render();toast('Error simulado. Puedes reintentar sobre la misma solicitud.');break;}case'retry-request':{const r=state.requests.find(x=>x.id===id);r.status='waiting';r.attempt++;event(state,r.caseId,'Reintento simulado',`Intento ${r.attempt}: se conservó el ID y la entidad sigue pendiente.`);save();render();toast('Reintento registrado sin duplicar la solicitud.');break;}case'decision':modal('Registrar una decisión ficticia','Este paso no acepta contratos ni confirma cobertura.',`<p>El escenario registrará que el cliente desea continuar con la opción presentada. Quedará pendiente la evidencia de emisión.</p><div class="form-actions">${button('Cancelar','close')}${button('Confirmar decisión simulada','confirm-decision',id,'primary')}</div>`);break;case'confirm-decision':{const c=caseBy(id);c.stage='emision';c.next='Verificar documento de nueva vigencia';event(state,id,'Decisión ficticia del cliente','Se registró interés en continuar. Emisión todavía pendiente.');save();close();render();break;}case'issue':modal('Verificar una emisión de muestra','Se creará una nueva vigencia ficticia, vinculada a la anterior.',`<p>El demo incorporará una carátula sintética, conservará la vigencia anterior y registrará la entrega simulada. No se emitirá ningún seguro real.</p><div class="form-actions">${button('Cancelar','close')}${button('Incorporar nueva vigencia ficticia','confirm-issue',id,'primary')}</div>`);break;case'confirm-issue':{const c=caseBy(id);if(c.stage!=='emision')throw Error('El caso no está pendiente de emisión.');const p=policy(c.policyId),r=state.requests.find(x=>x.id===c.selected);const pid=uid('p'),did=uid('d');p.status='Renovada';state.policies.push({...p,id:pid,status:'Registrada',number:p.number+'-REN',start:p.end,end:p.end.replace('2026','2027'),premium:r.quote.premium,insurer:insurer(r.insurerId).name,previousId:p.id,docId:did,validated:true});state.documents.push({id:did,policyId:pid,clientId:c.clientId,title:'Carátula de nueva vigencia · muestra',type:'Emisión ficticia',date:REFERENCE_DATE,source:'Emisión simulada',generated:true,status:'Revisado'});c.stage='cerrada';c.next='Seguimiento de la nueva vigencia';event(state,id,'Nueva vigencia incorporada · simulación','La póliza anterior se conservó. Se agregó una carátula sintética y se registró entrega simulada.');save();close();render();toast('Nueva vigencia ficticia registrada, con historia conservada.');break;}}}catch(err){toast(err.message,true);}});

document.addEventListener('submit',ev=>{const f=ev.target;if(!(f instanceof HTMLFormElement))return;ev.preventDefault();const fd=new FormData(f),v=Object.fromEntries(fd),id=f.dataset.id;const error=f.querySelector('.error-message');try{switch(f.id){case'global-search':location.hash='clientes?'+new URLSearchParams({q:v.query});break;case'filter-clients':location.hash='clientes?'+new URLSearchParams(v);break;case'filter-documents':location.hash='documentos?'+new URLSearchParams(v);break;case'filter-policies':location.hash='polizas?'+new URLSearchParams(v);break;case'filter-messages':location.hash='mensajes?'+new URLSearchParams(v);break;case'intake-form':validateIntake(state,id,v.end);save();close();render();toast('Revisión guardada y vinculada al documento fuente.');break;case'prepare-form':{const n=prepareRequests(state,id,fd.getAll('insurer'));save();close();render();toast(`${n} solicitudes preparadas. No se enviaron a entidades reales.`);break;}case'case-note':{const c=caseBy(id);if(!v.note.trim())throw Error('Escribe una gestión para guardarla.');c.next=v.next;c.due=v.due;noteCase(state,id,v.note);save();render();toast('Gestión y próxima acción guardadas.');break;}case'draft-form':sendDraft(state,id,v.body,f.dataset.template);f.dataset.sent='true';save();location.hash='mensajes?'+new URLSearchParams({caso:id});toast('Envío simulado registrado en la historia del caso.');break;case'client-form':{if(!v.name.trim()||!v.email.toLowerCase().endsWith('@example.com'))throw Error('Usa nombre ficticio y un correo terminado en @example.com.');const data={name:v.name.trim(),email:v.email,city:v.city,type:v.type,channel:v.channel,note:v.note,initials:v.name.trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('')};let c;if(id){c=client(id);Object.assign(c,data);}else{c={...data,id:uid('c'),identity:`DEMO-CLI-${state.clients.length+1}`,since:'2026'};state.clients.push(c);}event(state,null,id?'Ficha actualizada':'Cliente ficticio creado','Datos registrados para el ejercicio.',c.id);save();close();location.hash='cliente/'+c.id;render();toast('Expediente guardado.');break;}case'new-case-form':{const p=state.policies.find(p=>p.clientId===v.clientId&&p.product===v.product);const c={id:uid('r'),clientId:v.clientId,policyId:v.type==='Renovación'?p?.id||null:null,product:v.product,type:v.type,title:`${v.type} de ${v.product.toLowerCase()}`,stage:'preparacion',next:v.next,due:v.due,selected:null};if(v.type==='Renovación'&&!p)throw Error('Este cliente no tiene una póliza de ese producto en el ejercicio. Elige otra combinación o abre un negocio nuevo.');state.cases.push(c);event(state,c.id,'Caso abierto',`${c.type}: ${c.next}`);save();close();location.hash='caso/'+c.id;break;}case'commercial-lead':{const l=addLead(state,{...v,need:v.need+' · '+v.moment});save();location.hash='sitio/gracias/'+l.id;toast('Solicitud de muestra conectada a la mesa de trabajo.');break;}case'lead-form':addLead(state,v);save();close();location.hash='oportunidades';render();toast('Solicitud ficticia recibida. Ya aparece en nuevos negocios.');break;case'compose-form':saveCurrentDraft();close();location.hash=`borrador/${v.caseId}?tipo=${v.template}`;break;case'observation-form':if(!v.text.trim())throw Error('Escribe una observación para guardarla.');state.observations.unshift({...v,id:uid('ob'),text:v.text.trim(),at:demoTimestamp()});save();render();toast('Observación guardada para la discusión familiar.');break;case'interview-form':state.interview=v;save();toast('Respuestas guardadas. Puedes incluirlas en la exportación.');break;}}catch(err){if(error){error.textContent=err.message;error.scrollIntoView({block:'nearest'});}else toast(err.message,true);}});
window.addEventListener('hashchange',()=>{saveCurrentDraft();if(dialog.open)close();render();window.scrollTo({top:0,behavior:'instant'});document.getElementById('main').focus({preventScroll:true});});
window.addEventListener('beforeunload',saveCurrentDraft);
render();
